#!/usr/bin/env python3
"""Render the documented 100-round synthetic stress evidence."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'tools/cde/fresh-100-20261030'
REPORT = ROOT / 'docs/audits/fresh-reading-stress-100-2026-10-30.md'


def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()


def main():
    if REPORT.exists():
        raise FileExistsError(REPORT)
    data=json.loads((OUT/'verified-summary.json').read_text())
    lines=[]
    def add(s=''): lines.append(s)
    add('# Fresh reading-estimator stress evaluation — 100 rounds')
    add()
    add('**Result: 100 fresh synthetic rounds completed; not validated for real readers.** This report supplements the earlier [partial report](final-reading-stress-2026-10-30.md), whose historical results are not replaced. Generated by `python3 tools/cde/write_fresh_100_report.py` (exit 0).')
    add()
    add('## What was requested and done')
    add()
    add('The owner requested 100 fresh rounds after the earlier attempt only rescored old predictions. We generated fresh cases using distinct deterministic seeds, invoked the Swift estimator for every new input, captured 100 rounds of freshly seeded demo personas, and saved the inputs, outcomes, predictions, grades, Xcode logs and result bundles in [the evidence directory](../../tools/cde/fresh-100-20261030).')
    add()
    add('Each round contains 9,914 main cases: 4,004 synthetic development cases, 5,604 synthetic holdout-labelled cases, 234 corpus-development cases, 64 corpus-evaluation cases, and eight adversarial cases. Thus 100 rounds contain 991,400 main cases. Each also contains 16 newly seeded demo-persona cases; those 1,600 cases use a separate elapsed-time target. Together that is 993,000 case predictions, not 993,000 independent people. The generators use previously designed scenario recipes; seeds are new, recipes and book sets are not.')
    add()
    add('The corpus covers all 149 stored package rows in every round, two generated cases per package. Some rows share content digests. Package scores are stored features: the Swift estimator does not receive the actual books or their text. The synthetic generator uses fictional page sizes, response effects and future reading times. It produces four target cases per synthetic reader plus controls. Package scores and generated targets are not measurements of real people.')
    add()
    add('**SKIPPED: independent manual grading of every result.** Code scored and mechanically checked all main-case predictions. A human-style inspection of three extreme cases is described below; it is not a substitute for independent hand grades. **SKIPPED: sequential stop-on-spike, recalibrate and restart.** The model was frozen throughout, and scoring continued after spikes. Every round had at least one spike. **SKIPPED: real-reader and live-app accuracy validation**; actual interruptions, live page turns and storage reloads were not exercised.')
    add()
    add('## Method and frozen candidate')
    add()
    add('The app baseline is computed by the actual Swift `EstimationEngine` through the existing adversarial adapter. The experimental candidate blends that adapter’s recent and guarded predictions, using guarded weight 0.0011850789689659901 and recent weight 0.998814921031034. This weight was selected on previously inspected development cases before these fresh rounds; it was not retuned against these outcomes. It is not a production formula change. The same weight and candidate logic were used for all fresh rounds.')
    add()
    add('Rounds use seeds 86,000,000 + 100 × round plus fixed offsets for their independent generator calls. Identifiers are opaque hashes. Future outcomes were not supplied to the Swift estimator. Cases were scored after predictions were obtained; all rounds used the same generator families and fixed split definitions, so these are not independently designed blind tests. The four synthetic controls repeat the same design each round; randomized synthetic histories and outcomes use new seeds.')
    add()
    add('The demo test generates a fresh library with the persona’s normal generator and a per-round simulation seed. For one eligible book, it withholds the last 40 closed page timings and estimates using only timings closed by the first withheld timing. The held-back sum is **generated elapsed time over 40 visits**, not measured active time or necessarily 40 distinct remaining pages. Demo results are therefore reported separately. The detailed attachment contains every demo input and the withheld durations.')
    add()
    add('Absolute percentage error is `100 × |prediction − synthetic target| / synthetic target`. A spike is an absolute error greater than both 300 seconds and 75% of the synthetic target. This is an investigation rule, not a validated pass/fail threshold. The 90th percentile is the sorted value at Python index `round((n − 1) × 0.9)`. Percentages are rounded in this report; full precision is in [verified-summary.json](../../tools/cde/fresh-100-20261030/verified-summary.json).')
    add()
    add('## Main results')
    add()
    add('| Dataset / model | Cases | Median error % | Mean error % | 90th percentile % | Worst error % | Spikes |')
    add('|---|---:|---:|---:|---:|---:|---:|')
    def table(label, bucket):
        for name,key,sp in [('production baseline','baseline','baseline_spikes'),('experimental candidate','candidate','candidate_spikes')]:
            m=bucket[key]; add(f"| {label} — {name} | {m['cases']} | {m['median_ape']:.2f} | {m['mean_ape']:.2f} | {m['p90_ape']:.2f} | {m['max_ape']:.2f} | {bucket[sp]} |")
    table('All main cases',data['overall'])
    for group in sorted(data['groups']): table(group,data['groups'][group])
    table('Demo elapsed-time targets',data['demo'])
    add()
    add('In these synthetic cases, the candidate’s overall median is lower, but its worst main-case error is higher. In the synthetic holdout-labelled family it has more spikes than the baseline, and the corpus evaluation family also worsens. The evaluation families and recipes are public and previously inspected, so this is not independent validation. The extreme errors make the candidate unsuitable for a production change on this evidence.')
    add()
    add('## Severe cases inspected individually')
    add()
    add('- Round 29, ID `7610b1d828f009e9c071`: synthetic active target 757.93 seconds; baseline 1,061.54; candidate 28,262.53; candidate error 3,628.89%. The target history contains only two long page intervals (718.42 and 694.70 seconds), while earlier history includes much shorter intervals. The generator’s interruption recipe can inject idle time; this is not evidence that any real reader was interrupted.')
    add('- Round 18, ID `c0ac5bcbcfe2162778bd`: synthetic target 674.52 seconds; baseline 925.59; candidate 24,497.37; candidate error 3,531.84%. The two target intervals are 680.12 and 544.75 seconds. The candidate heavily overreacts to this sparse target history.')
    add('- Round 59, ID `4fd1468cbf1c0237dd41`: synthetic target 676.40 seconds; baseline and candidate both 20,057.05; error 2,865.27%. One prior book has twelve intervals above 800 seconds while another has short intervals. The shown data support a cross-book pace contamination risk but do not identify a real reader’s cause.')
    add()
    add('These are manual inspections of examples, not independent grades of all cases. Original per-case histories, predictions and generated outcomes remain in the batch receipts.')
    add()
    add('## All 100 rounds')
    add()
    add('Each row contains the 9,914 main cases. Demo cases are summarized separately above. All numbers are automated assessments against generated outcomes; no round was restarted after a spike.')
    add()
    add('| Round | Baseline median % | Candidate median % | Baseline mean % | Candidate mean % | Baseline worst % | Candidate worst % | Baseline spikes | Candidate spikes | First candidate spike position |')
    add('|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|')
    for r in data['rounds']:
        b,c=r['baseline'],r['selected']; add(f"| {r['round']} | {b['median_pct']:.2f} | {c['median_pct']:.2f} | {b['mean_pct']:.2f} | {c['mean_pct']:.2f} | {b['max_pct']:.2f} | {c['max_pct']:.2f} | {r['baseline_spikes']} | {r['selected_spikes']} | {r['first_selected_spike']} |")
    add()
    add('## Evidence and checks')
    add()
    add('- Bundle delivery smoke: Xcode test exited 0 and returned the expected 2,400-second baseline for a 40-page, 60-second-per-page fixture. The old request-file approach stalled; the new test bundle route does not determine the original macOS stall’s root cause.')
    add('- Round 1: Xcode returned 9,914 predictions. Rounds 2–100 were run in ten bounded Xcode batches by `bash tools/cde/run_fresh_100.sh`, exit 0. Each batch has input, truth, prediction, graded and summary JSON, a result bundle and logs. Initial generation had a syntax error, then was corrected; the failed and retry logs remain in the evidence directory.')
    add('- Demo rounds: the first separate runs and a detailed re-run exited 0. All 1,600 detailed demo outcomes and candidate predictions matched the first runs within floating-point tolerance, and each held-back duration sum matched its saved target. This is reproducibility, not a second set of independent demo observations.')
    add('- `python3 tools/cde/review_fresh_100.py` exited 0. It checked coverage, ID uniqueness, predictions, outcome values, arithmetic, spike flags, round metrics and demo rerun matching. It is an automated verification, not a manual review of every case. [Verification log](../../tools/cde/fresh-100-20261030/verify.log).')
    add('- `python3 -m unittest discover -s tools/cde -p \'test_fresh_100.py\' -v` exited 0: one generator reproducibility and isolation test passed. `python3 -m unittest discover -s tools/cde -p \'test_adversarial_eval.py\' -v` exited 0: three tests passed.')
    add('- `./scripts/verify-sentinel-surface.sh` exited 0; `python3 scripts/comprehension-bench.py --validate-only` exited 0. `./scripts/census.sh --unit-only` exited 0: Xcode summary reported 498 passed, 0 failed and 9 skipped, for 507 total. Skips are not passes. See [census receipt](../../tools/cde/fresh-100-20261030/census.log).')
    add('- [Verified summary](../../tools/cde/fresh-100-20261030/verified-summary.json) records exact per-batch SHA-256 fingerprints of input, truth, prediction, grading and summary files. The test-bundle Swift attachment exports are preserved alongside them. The full demo attachment is named in the verified summary and its manifest.')
    add()
    add('### Evidence digests')
    add()
    for p in [OUT/'verified-summary.json',OUT/'verify.log',ROOT/'tools/cde/fresh_100.py',ROOT/'tools/cde/review_fresh_100.py',ROOT/'tools/cde/write_fresh_100_report.py']:
        add(f'- [{p.name}](../../{p.relative_to(ROOT)}) — SHA-256 `{sha(p)}`.')
    add()
    add('## Limitations and next decision')
    add()
    add('The synthetic data reuse fixed recipes and scored package metadata, not measured reader behavior. The adapter receives closed intervals, whereas live sessions and SQLite summary reload can differ. Navigation intent, interruptions, word counts and future visits are not independently observed. An unbiased production evaluation needs an independently designed dataset with consented real outcomes, a defined independent grading process, and tests through live recording and reload paths. The fixed candidate remains experimental; no production weights were changed.')
    REPORT.write_text('\n'.join(lines)+'\n')
    print('wrote',REPORT.relative_to(ROOT),'lines',len(lines),'sha256',sha(REPORT))


if __name__=='__main__':
    main()
